import{_ as s,C as n,o as e,c as u,a2 as r,j as i,E as l,a as o}from"./chunks/framework.C21TwvGF.js";const O=JSON.parse('{"title":"22-dars (Mentor). 22-dars: Flowalgorithm orqali dasturlash tushunchalari: dastur, buyruq, kod va mantiq","description":"","frontmatter":{"title":"22-dars (Mentor). 22-dars: Flowalgorithm orqali dasturlash tushunchalari: dastur, buyruq, kod va mantiq","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":8,"link":"/mentor/8-sinf-cs/hafta-08/"},"g":22,"title":"22-dars: Flowalgorithm orqali dasturlash tushunchalari: dastur, buyruq, kod va mantiq","lead":"Flowalgorithm orqali dasturlash tushunchalari: dastur, buyruq, kod va mantiq","slide":"/slaydlar/8-sinf-cs/hafta-08/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-08/dars-1-test.html","student_link":"/8-sinf-cs/hafta-08/dars-1","tabs":[{"g":22,"link":"/mentor/8-sinf-cs/hafta-08/dars-1","current":true},{"g":23,"link":"/mentor/8-sinf-cs/hafta-08/dars-2","current":false},{"g":24,"link":"/mentor/8-sinf-cs/hafta-08/dars-3","current":false}],"prev":null,"next":{"g":23,"title":"23-dars: Flowalgorithmda o‘zgaruvchilar va ma’lumot turlari bilan ishlash","link":"/mentor/8-sinf-cs/hafta-08/dars-2"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-08/dars-1.md","filePath":"mentor/8-sinf-cs/hafta-08/dars-1.md"}'),d={name:"mentor/8-sinf-cs/hafta-08/dars-1.md"},h={class:"blk"},m={id:"dars-rejasi",tabindex:"-1"},g={class:"blk"},c={id:"mentor-konspekti",tabindex:"-1"},q={class:"blk"},p={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},y={class:"blk"},b={id:"tezkor-nazorat-savollari",tabindex:"-1"},k={class:"blk"},f={id:"uyga-vazifa",tabindex:"-1"};function v(_,a,z,I,P,x){const t=n("Icon");return e(),u("div",null,[a[16]||(a[16]=r("<p><strong>Fan:</strong> Computer Science Foundation<br><strong>Sinf:</strong> 8-sinf<br><strong>Hafta:</strong> 8-hafta (1-dars)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Format:</strong> Nazariy tushunchalar (30 daqiqa) + Kompyuterda Flowgorithm amaliyoti (45 daqiqa) + Xulosa (5 daqiqa)</p><hr>",2)),i("div",h,[i("h2",m,[l(t,{name:"file-text"}),a[0]||(a[0]=o(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r("<ol><li><strong>Tashkiliy qism va o&#39;tgan mavzuni takrorlash (10 daqiqa)</strong><ul><li>O&#39;tgan 7-haftadagi Flowgorithm interfeysi, asosiy bloklar va «Salom, dunyo!» dasturini eslash.</li><li>Tezkor savol-javob: Start/End vazifasi nima? Output bloki nima uchun kerak? Qo&#39;shtirnoq qachon qo&#39;yiladi?</li></ul></li><li><strong>Yangi mavzu bayoni: Dasturlash tushunchalari va IPO modeli (20 daqiqa)</strong><ul><li>Dastur (Program) nima? Buyruq (Instruction) va Kod (Code) tushunchalari.</li><li>Algoritm va dastur o&#39;rtasidagi farq.</li><li>Dastur mantiqining yuragi: <strong>IPO modeli</strong> (Input — Process — Output).</li><li>Flowgorithm orqali dastur mantig&#39;ini vizual ifodalash va kompyuter qanday fikrlashini tushunish.</li></ul></li><li><strong>Amaliy laboratoriya mashg&#39;uloti: Flowgorithmda IPO loyihalari (45 daqiqa)</strong><ul><li>1-mashq: Oddiy IPO zanjirini tuzish (foydalanuvchi ismini qabul qilib, unga salom berish).</li><li>2-mashq: Matematik ifodalarning mantiqiy ketma-ketligi (son kiritish va uni 2 barobar oshirib chiqarish).</li><li>3-mashq: Mustaqil va juftlikda topshiriqlarni bajarish.</li></ul></li><li><strong>Darsni yakunlash va baholash (5 daqiqa)</strong><ul><li>Tezkor nazorat savollari.</li><li>Uyga vazifani tushuntirish.</li></ul></li></ol><hr>",2))]),i("div",g,[i("h2",c,[l(t,{name:"file-text"}),a[3]||(a[3]=o(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_1-dastur-buyruq-va-kod-nima" tabindex="-1">1. Dastur, Buyruq va Kod nima? <a class="header-anchor" href="#_1-dastur-buyruq-va-kod-nima" aria-label="Permalink to &quot;1. Dastur, Buyruq va Kod nima?&quot;">​</a></h3><ul><li><strong>Kompyuter dasturi (Computer Program):</strong> Kompyuter aniq bir masalani yoki vazifani bajarishi uchun mo&#39;ljallangan buyruqlar to&#39;plami. Kompyuter o&#39;z-o&#39;zidan mustaqil fikrlay olmaydi — u faqat dasturchi yozgan ko&#39;rsatmalarni so&#39;zsiz bajaradi.</li><li><strong>Buyruq (Instruction):</strong> Kompyuter tushuna oladigan eng kichik, bo&#39;linmas harakat. Masalan: <code>X ga 5 ni yoz</code>, <code>A va B ni qo&#39;sh</code>, <code>Ekranga chiqargin</code>.</li><li><strong>Kod (Source Code):</strong> Buyruqlarning ma&#39;lum bir dasturlash tili sintaksisi yoki qoidalari asosida yozilgan matni.</li><li><strong>Algoritm vs Dastur:</strong><ul><li><em>Algoritm</em> — masalani yechishning umumiy g&#39;oyasi va qadamlar rejasi (odam uchun ham, kompyuter uchun ham tushunarli bo&#39;lishi mumkin).</li><li><em>Dastur</em> — shu algoritmning kompyuter to&#39;g&#39;ridan-to&#39;g&#39;ri ijro eta oladigan shaklga (kodga yoki blok-sxemaga) o&#39;girilgan ko&#39;rinishi.</li></ul></li></ul><h3 id="_2-dastur-mantiqi-ipo-modeli-input-—-process-—-output" tabindex="-1">2. Dastur mantiqi: IPO modeli (Input — Process — Output) <a class="header-anchor" href="#_2-dastur-mantiqi-ipo-modeli-input-—-process-—-output" aria-label="Permalink to &quot;2. Dastur mantiqi: IPO modeli (Input — Process — Output)&quot;">​</a></h3><p>Dunyo bo&#39;yicha deyarli barcha dasturlar bitta universal mantiq asosida ishlaydi: $$\\text{Input (Kiritish)} \\longrightarrow \\text{Process (Qayta ishlash)} \\longrightarrow \\text{Output (Natija chiqarish)}$$</p><ol><li><strong>Input (Kiritish):</strong> Dastur ishlashi uchun tashqaridan ma&#39;lumot qabul qilinadi. Manbalar: foydalanuvchi klaviaturasi, sichqoncha, fayl, internet yoki sensorlar.</li><li><strong>Process (Qayta ishlash / Hisoblash):</strong> Kiritilgan ma&#39;lumotlar ustida amallar bajariladi: matematik formulalar, taqqoslashlar, saralash yoki o&#39;zgartirish. Bu ishni markaziy protsessor (CPU) bajaradi.</li><li><strong>Output (Chiqarish):</strong> Qayta ishlash natijasi foydalanuvchiga taqdim etiladi: monitor ekrani, dinamik ovozi, printer qog&#39;ozi yoki fayl.</li></ol><blockquote><p><strong>Hayotiy o&#39;xshatish:</strong> Sharbat chiqargich (Sokovijimalka).</p><ul><li><em>Input:</em> Olma solinadi.</li><li><em>Process:</em> Pichoqlar aylanib, meva siqiladi va sharbati ajratiladi.</li><li><em>Output:</em> Stakanga olma sharbati quyiladi.</li></ul></blockquote><h3 id="_3-flowgorithmda-dastur-mantig-ini-vizual-ifodalash" tabindex="-1">3. Flowgorithmda dastur mantig&#39;ini vizual ifodalash <a class="header-anchor" href="#_3-flowgorithmda-dastur-mantig-ini-vizual-ifodalash" aria-label="Permalink to &quot;3. Flowgorithmda dastur mantig&#39;ini vizual ifodalash&quot;">​</a></h3><p>Flowgorithm dasturida dasturchi kod yozishdan oldin buyruqlar mantiqini ko&#39;z bilan ko&#39;rib chiqadi:</p><ol><li><code>Declare</code> — kompyuter xotirasida ma&#39;lumot saqlash uchun joy ajratish.</li><li><code>Input</code> — foydalanuvchidan ma&#39;lumot so&#39;rash.</li><li><code>Assign</code> — kiritilgan qiymat ustida arifmetik yoki mantiqiy amal bajarish.</li><li><code>Output</code> — hisoblangan natijani ekranga ko&#39;rsatish.</li></ol><hr>',10))]),i("div",q,[i("h2",p,[l(t,{name:"file-text"}),a[6]||(a[6]=o(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=r('<h3 id="_1-topshiriq-salomlashish-dasturi-ipo-modeli-·-oson" tabindex="-1">1-topshiriq: Salomlashish dasturi (IPO modeli) · oson <a class="header-anchor" href="#_1-topshiriq-salomlashish-dasturi-ipo-modeli-·-oson" aria-label="Permalink to &quot;1-topshiriq: Salomlashish dasturi (IPO modeli) · oson&quot;">​</a></h3><p>Foydalanuvchidan ismini so&#39;rab, ekranga «Salom, [Ism]! Dasturlash olamiga xush kelibsiz!» deb chiqaruvchi dastur blok-sxemasini tuzing.</p><p><strong>Yechim:</strong> Flowgorithm bloklar ketma-ketligi:</p><ol><li><code>Declare String ism</code></li><li><code>Output &quot;Ismingizni kiriting:&quot;</code></li><li><code>Input ism</code></li><li><code>Output &quot;Salom, &quot; &amp; ism &amp; &quot;! Dasturlash olamiga xush kelibsiz!&quot;</code><em>(Izoh: Flowgorithmda matnlarni birlashtirish (konkatenatsiya) uchun <code>&amp;</code> (ampersand) belgisi ishlatiladi).</em></li></ol><hr><h3 id="_2-topshiriq-sonni-2-barobar-oshirish-·-oson" tabindex="-1">2-topshiriq: Sonni 2 barobar oshirish · oson <a class="header-anchor" href="#_2-topshiriq-sonni-2-barobar-oshirish-·-oson" aria-label="Permalink to &quot;2-topshiriq: Sonni 2 barobar oshirish · oson&quot;">​</a></h3><p>Foydalanuvchi bitta butun son kiritadi. Dastur ushbu sonni 2 ga ko&#39;paytirib, ekranga natijani chiqarishi kerak.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Integer son, natija</code></li><li><code>Output &quot;Ixtiyoriy son kiriting:&quot;</code></li><li><code>Input son</code></li><li><code>Assign natija = son * 2</code></li><li><code>Output &quot;Kiritilgan sonning 2 barobari: &quot; &amp; natija</code></li></ol><hr><h3 id="_3-topshiriq-do-kondagi-xarid-hisobi-·-o-rta" tabindex="-1">3-topshiriq: Do&#39;kondagi xarid hisobi · o&#39;rta <a class="header-anchor" href="#_3-topshiriq-do-kondagi-xarid-hisobi-·-o-rta" aria-label="Permalink to &quot;3-topshiriq: Do&#39;kondagi xarid hisobi · o&#39;rta&quot;">​</a></h3><p>Daftarning narxi 3000 so&#39;m. Foydalanuvchi necha dona daftar sotib olmoqchiligini kiritadi. Dastur to&#39;lanishi kerak bo&#39;lgan umumiy summani hisoblab bersin.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Integer soni, jami</code></li><li><code>Output &quot;Nechta daftar olasiz?&quot;</code></li><li><code>Input soni</code></li><li><code>Assign jami = soni * 3000</code></li><li><code>Output &quot;Jami to&#39;lov: &quot; &amp; jami &amp; &quot; so&#39;m&quot;</code></li></ol><hr><h3 id="_4-topshiriq-ipo-tahlili-—-foydalanuvchi-yoshi-·-o-rta" tabindex="-1">4-topshiriq: IPO tahlili — Foydalanuvchi yoshi · o&#39;rta <a class="header-anchor" href="#_4-topshiriq-ipo-tahlili-—-foydalanuvchi-yoshi-·-o-rta" aria-label="Permalink to &quot;4-topshiriq: IPO tahlili — Foydalanuvchi yoshi · o&#39;rta&quot;">​</a></h3><p>Foydalanuvchidan tug&#39;ilgan yilini so&#39;rang va hozirgi yil (2026) asosida uning taxminiy yoshini hisoblab chiqaring.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Integer tugilganYil, yosh</code></li><li><code>Output &quot;Tug&#39;ilgan yilingizni kiriting:&quot;</code></li><li><code>Input tugilganYil</code></li><li><code>Assign yosh = 2026 - tugilganYil</code></li><li><code>Output &quot;Siz taxminan &quot; &amp; yosh &amp; &quot; yoshdasiz.&quot;</code></li></ol><hr><h3 id="_5-topshiriq-uchta-sonning-o-rtacha-qiymati-·-qiyin" tabindex="-1">5-topshiriq: Uchta sonning o&#39;rtacha qiymati · qiyin <a class="header-anchor" href="#_5-topshiriq-uchta-sonning-o-rtacha-qiymati-·-qiyin" aria-label="Permalink to &quot;5-topshiriq: Uchta sonning o&#39;rtacha qiymati · qiyin&quot;">​</a></h3><p>Foydalanuvchidan 3 ta haqiqiy son qabul qilib, ularning o&#39;rtacha arifmetik qiymatini hisoblovchi blok-sxema tuzing.</p><p><strong>Yechim:</strong></p><ol><li><code>Declare Real a, b, c, orta</code></li><li><code>Output &quot;Uchta son kiriting:&quot;</code></li><li><code>Input a</code></li><li><code>Input b</code></li><li><code>Input c</code></li><li><code>Assign orta = (a + b + c) / 3</code></li><li><code>Output &quot;O&#39;rtacha arifmetik: &quot; &amp; orta</code></li></ol><hr>',25))]),i("div",y,[i("h2",b,[l(t,{name:"file-text"}),a[9]||(a[9]=o(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=i("ol",null,[i("li",null,"Kompyuter dasturi va algoritm o'rtasida qanday farq bor?"),i("li",null,"IPO qisqartmasi nimani anglatadi va har bir bosqich qanday vazifani bajaradi?"),i("li",null,"Dasturda buyruqlar qanday tartibda bajariladi (chiziqli holda)?"),i("li",null,"Flowgorithmda matn bilan o'zgaruvchini birlashtirishda qaysi belgidan foydalaniladi?"),i("li",null,"Agar Input bloki qo'yilmasa, dastur tashqaridan ma'lumot ola biladimi?")],-1)),a[12]||(a[12]=i("hr",null,null,-1))]),i("div",k,[i("h2",f,[l(t,{name:"house"}),a[13]||(a[13]=o(" Uyga vazifa ",-1)),a[14]||(a[14]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[15]||(a[15]=i("ol",null,[i("li",null,"Uyga vazifa faylidagi 22-dars topshirig'ini Flowgorithmda bajarish."),i("li",null,"Kundalik hayotingizdagi 3 ta qurilma (masalan: bankomat, svetofor, mikroto'lqinli pech) uchun IPO modelini daftaringizga jadval ko'rinishida yozib kelish."),i("li",null,[o("Flowgorithmda "),i("code",null,"F6"),o(" (Step) tugmasi yordamida buyruqlarning bajarilish ketma-ketligini kuzatish.")])],-1))])])}const D=s(d,[["render",v]]);export{O as __pageData,D as default};
